function applyRuntime(value:RuntimeSession){if(value.generation<runtimeSession.value.generation||(value.generation===runtimeSession.value.generation&&value.updatedAt<runtimeSession.value.updatedAt))return;runtimeSession.value=value;if(value.status==='failed'&&value.error?.startsWith('[PLAYER_TRANSPORT_FAILED]')){playbackError.value=value.error;playbackCode.value='PLAYER_TRANSPORT_FAILED';status.value=value.error;}if(value.domain!=='vod'){lastFailed.value=null;autoAdvanceLocked=false;consumedEofLoadId='';}}
