async function resumeQueueItem(item:PlaybackHistoryEntry,initiator:'user'|'auto-next'|'history'='history',fromEpisodeId?:string){if(!item.flag||!item.episodeId){status.value='该记录来自旧版本，缺少重播参数；请从点播详情重新播放一次。';return;}try{await window.desktop.playback.play({sourceId:item.sourceId,videoId:item.videoId,videoName:item.videoName,flag:item.flag,episodeId:item.episodeId,episodeName:item.episodeName,initiator,...(initiator==='auto-next'&&fromEpisodeId?{fromEpisodeId}:{}),...(item.poster?{poster:item.poster}:{}),...(item.episodes?.length?{episodeListJson:JSON.stringify(item.episodes)}:{})});if(!queuePersisted.value)queue.value=await window.desktop.history.list(8);consumedEofLoadId='';lastFailed.value=null;playbackError.value='';playbackCode.value='';status.value='已继续播放：'+item.videoName+' · '+item.episodeName;await nextTick();scheduleSurfaceSync();}catch(error){const message=error instanceof Error?error.message:String(error);if(message.includes('PLAYBACK_SUPERSEDED'))return;lastFailed.value=item;playbackError.value=message;playbackCode.value=playbackCodeOf(playbackError.value);status.value=playbackError.value;}}
